#[derive(Clone,Copy)]enum Op{Advance,Cancel,Original}
struct Context<'a,'b>{turn:&'a OriginalSourceTurn,op:Op,original:Option<&'a mut OriginalRetirementCloseLoan<'b>>}
struct Producer{birth:ManuallyDrop<ReadRegistryBirth<u64>>,turn:OriginalSourceTurnIdentity}
impl Drop for Producer{fn drop(&mut self){if std::thread::panicking(){return}assert!(self.birth.terminal_is_empty());unsafe{ManuallyDrop::drop(&mut self.birth)}}}
impl OriginalEffectProducer for Producer{
 type Output=RetainedCloneStep;type Failure=OriginalRetirementFailure;type Context<'a,'b>=Context<'a,'b> where 'b:'a;
 fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError>where 'b:'a{if c.turn.identity()!=self.turn{return Err(ValueError::invariant("read registry birth changed Source"))}Ok(())}
 fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity>where 'b:'a{Some(c.turn.identity())}
 fn receive<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{match c.op{Op::Advance=>self.birth.advance_into(4096,4096,effect,reply),Op::Cancel=>self.birth.cancel_into(4096,4096,effect,reply),Op::Original=>self.birth.cancel_original_into(c.original.as_deref_mut().ok_or_else(||ValueError::invariant("original read loan absent"))?,4096,effect,reply)}}
 fn recover<'r,'a,'b>(&mut self,c:&mut Self::Context<'a,'b>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,Self::Output,Self::Failure>)->Result<OriginalEffectReplyComplete<'r,Self::Output,Self::Failure>,ValueError>where 'b:'a{match c.op{Op::Advance=>Err(ValueError::invariant("native birth has no pending producer callback")),Op::Cancel=>self.birth.recover_cancel_into(4096,effect,reply),Op::Original=>self.birth.recover_cancel_original_into(c.original.as_deref_mut().ok_or_else(||ValueError::invariant("original read loan absent"))?,4096,effect,reply)}}
}
impl OriginalEffectBirthProducer for Producer{type Original<'loan>=OriginalRetirementCloseLoan<'loan>;fn requires_original_birth(&self)->bool{self.birth.requires_original_birth()}fn close_original_birth<'a,'b,'loan>(&mut self,_:&mut Self::Context<'a,'b>,original:&mut Self::Original<'loan>,grant:RetainedCloneGrant)->RetainedWorkPoll<RetainedCloneStep,Self::Failure>where 'b:'a{self.birth.close_original_birth_step(original,grant)}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]fn issued_registry_birth_and_cancellation_use_one_actual_decoder_source(){let law:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();assert_eq!(law["capacity"],1024);let turns=256u64;let limit=4096u64;let stock=serde_json::json!({"items":turns,"copyBytes":turns*limit,"capacityBytes":turns*limit,"releaseBytes":turns*limit,"depth":64,"fuel":turns*limit});let mut bank=source_bank::Bank::from_stock(&stock,false);let mut recipient=NativeDecodeRetirementRecipient::new();let mut observer=|_|true;let mut native=NativeDecodeControl::new((turns*limit)as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut authority=OriginalEffectAuthority::new(Producer{birth:ManuallyDrop::new(ReadRegistryBirth::new()),turn:bank.turn.identity()});let mut frame=NativeReceivingEffect::default();let mut closing=false;let mut prepared=false;let mut ready=false;for _ in 0..turns{if !closing&&authority.inspect(|p|p.birth.ready()){ready=true;closing=true}if closing&&authority.inspect(|p|p.birth.terminal_is_empty()){break}if authority.inspect(|p|p.birth.registry_prepared()){prepared=true}let(d,work)=authority.inspect(|p|if closing{(p.birth.cancel_demand(4096,4096).unwrap(),p.birth.cancel_work_demand(4096,4096).unwrap())}else{(p.birth.advance_demand(4096,4096).unwrap(),p.birth.advance_work_demand(4096,4096).unwrap())});assert!(d.copy_bytes<=4096,"read registry turn exceeds the original copy limit");let g=grant(d);if closing&&authority.inspect(|p|p.birth.requires_original_birth()){let poll=bank.run_with_turn(&mut native,|turn,control|control.with_retirement(g,|funding|funding.with_original_close(|original|{let mut c=Context{turn,op:Op::Cancel,original:None};authority.drive_original_birth(&mut c,original,g)}))).unwrap();if let RetainedWorkPoll::Complete(turn)=poll{turn.result.unwrap();}continue}let original=closing&&authority.inspect(|p|p.birth.requires_original_control());let poll=bank.run_with_turn(&mut native,|turn,control|control.receive_original_effect(d,work,&mut frame,&mut authority,|native,effect,authority,action|if original{native.with_retirement(g,|funding|funding.with_original_close(|loan|{let mut c=Context{turn,op:Op::Original,original:Some(loan)};authority.drive(&mut c,effect,action)}))}else{let mut c=Context{turn,op:if closing{Op::Cancel}else{Op::Advance},original:None};authority.drive(&mut c,effect,action)})).unwrap();if let NativeReceivingEffectPoll::Complete(turn)=poll{turn.result.unwrap();}}assert!(prepared&&ready);assert!(authority.inspect(|p|p.birth.terminal_is_empty()));drop(authority.into_producer().ok().unwrap())}

